INSERT IGNORE INTO `base_translation` (`target_type`, `target_id`, `locale`, `name`) VALUES (1, 3003, 'es-ES', '<h2>Política de privacidad</h2><p>Gracias por utilizar esta aplicación. Valoramos y protegemos tus datos personales y solo los tratamos cuando es necesario para el inicio de sesión, las funciones de la aplicación y la atención al cliente.</p><h3>I. Uso de la información</h3><p>Utilizamos tus datos conforme a la legislación aplicable y a esta política, y no los destinamos a fines ajenos.</p><h3>II. Tus derechos</h3><p>Puedes consultar, corregir o eliminar tus datos personales conforme a la ley, o contactarnos mediante los canales publicados en la aplicación.</p>');
INSERT IGNORE INTO `base_translation` (`target_type`, `target_id`, `locale`, `name`) VALUES (1, 3004, 'es-ES', '<h2>Términos del servicio</h2><p>Te damos la bienvenida a esta aplicación. Lee y comprende este acuerdo y sus reglas antes de utilizarla. Al usar los servicios de la aplicación aceptas cumplirlos.</p><h3>I. Uso del servicio</h3><p>Utiliza cada función de forma legal y conforme a las indicaciones de la página. No uses esta aplicación para actividades ilegales o que infrinjan los derechos de otras personas.</p><h3>II. Cambios del acuerdo</h3><p>Podemos actualizar este acuerdo según los cambios del negocio y de la legislación, y mostraremos la versión actualizada en la aplicación.</p>');
